// Per-fighter generated files. Each fighter's rows live in their own file named by its roster slug, so re-exporting
// one fighter rewrites only that file, and a small index lists the fighters and changes only when one gains a file.
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import type { ModelFacts } from '../../ts/node_modules/wisp/host/models/models';
import { fighterArt } from '../../ts/src/generated/fighterArtData';

const ts = resolve(import.meta.dir, '../../ts');
export const CLIPS = join(ts, 'src/generated/clips');
export const CLIP_INDEX = join(CLIPS, 'fighterOriginalClipInfo.ts');
export const WHITE_MODELS = join(ts, 'src/generated/assets/white-models');
export const WHITE_MODEL_INDEX = join(ts, 'src/generated/assets/whiteFighterModels.ts');
export const WHITE_FACTS = join(ts, 'src/generated/assets/white-facts');
export const WHITE_FACT_INDEX = join(ts, 'src/generated/assets/whiteModelFacts.ts');

const CLIP_PRODUCER = '// Generated by tools/animations/export-original-clips.ts from the original fighter models; regenerate instead of editing.';
const WHITE_PRODUCER = '// Generated by tools/animations/white-flash-models.ts; regenerate instead of editing.';

/** The name an index imports a fighter's file under: "kael'thas-sunstrider" is kaelthasSunstrider. */
export const shardName = (slug: string) => slug.replaceAll('\'', '').replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase());

/** The fighters an index lists: the ones it already lists, then any other fighter whose file exists, by character number. */
export function shardOrder(index: string, directory: string, extension: string, characters: Iterable<number>): number[] {
    const bySlug = new Map([...characters].map(character => [fighterArt(character).slug, character]));
    const text = existsSync(index) ? readFileSync(index, 'utf8') : '';
    const listed = [...text.matchAll(/^(?:import \* as \w+ from "\.\/(?:[\w-]+\/)?|  ")([^"/]+)"[;,]$/gm)].map(match => bySlug.get(match[1]!));
    const present = [...bySlug.values()].filter(character => existsSync(join(directory, `${fighterArt(character).slug}${extension}`)));
    return [...new Set([...listed.filter(character => character !== undefined && present.includes(character)), ...present])] as number[];
}

/** One fighter's clips, as clip and sequence-name literal lines, and its light model. */
export function clipFile(name: string, clips: readonly string[], names: readonly string[], light: string | undefined): string {
    const lines = [...clips, ...names];
    return [CLIP_PRODUCER,
        `// ${name}'s clips by original sequence index, lowercase original sequence names (a name without its numeric variant selects the first variant) and light model.`,
        ...lines.some(line => line.includes('f32(')) ? ['import { f32 } from "wisp/src/sim/f32";'] : [],
        'import type { FighterOriginalClip } from "./fighterOriginalClip";',
        '',
        'export const clips: readonly FighterOriginalClip[] = [', ...clips.map(line => `  ${line}`), '];',
        '',
        'export const names: ReadonlyMap<string, number> = new Map<string, number>([', ...names.map(line => `  ${line}`), ']);',
        '',
        `export const light: string | undefined = ${light === undefined ? 'undefined' : JSON.stringify(light)};`,
    ].join('\n') + '\n';
}

/** The clip type every fighter's file shares. */
export const clipTypeFile = () => [CLIP_PRODUCER,
    'export interface FighterOriginalClip {',
    '  readonly modelPath: string;',
    '  readonly timeline?: boolean;',
    '  readonly startSeconds: number;',
    '  readonly endSeconds: number;',
    '  readonly looping: boolean;',
    '}',
].join('\n') + '\n';

/** The clip index: the light gate, then each listed character's file. */
export function clipIndex(characters: readonly number[], gate: {activeAnimation: string, inactiveAnimation: string, seconds: string}): string {
    return [CLIP_PRODUCER,
        '// The original-model clip pool: one model per original sequence, so a clip plays by setting its time.',
        '// Each fighter\'s clips are in its own file, which a re-export rewrites alone; this index changes only when a fighter is added.',
        ...gate.seconds.includes('f32(') ? ['import { f32 } from "wisp/src/sim/f32";'] : [],
        'import type { FighterOriginalClip } from "./fighterOriginalClip";',
        ...characters.map(character => `import * as ${shardName(fighterArt(character).slug)} from "./${fighterArt(character).slug}";`),
        '',
        '/** The light model\'s animation while its fighter is shown, and while hidden. */',
        `export const ORIGINAL_LIGHT_ACTIVE_ANIMATION = ${JSON.stringify(gate.activeAnimation)};`,
        `export const ORIGINAL_LIGHT_INACTIVE_ANIMATION = ${JSON.stringify(gate.inactiveAnimation)};`,
        `export const ORIGINAL_LIGHT_GATE_SECONDS = ${gate.seconds};`,
        '',
        'interface FighterClips {',
        '  readonly clips: readonly FighterOriginalClip[];',
        '  readonly names: ReadonlyMap<string, number>;',
        '  readonly light: string | undefined;',
        '}',
        '',
        '/** Each character\'s clips by original sequence index, sequence names and light model. */',
        'const FIGHTERS: Readonly<Record<number, FighterClips>> = {',
        ...characters.map(character => `  ${character}: ${shardName(fighterArt(character).slug)},`),
        '};',
        '',
        '/** Clips 0 to count - 1 exist for this character. */',
        'export function originalClipCount(character: number): number {',
        '  return FIGHTERS[character]?.clips.length ?? 0;',
        '}',
        '',
        '/** The light model that accompanies this character\'s clips, if it has one. */',
        'export function originalLightPath(character: number): string | undefined {',
        '  return FIGHTERS[character]?.light;',
        '}',
        '',
        '/** The clip for an original sequence index; times are seconds within the clip. */',
        'export function originalClip(character: number, sequenceIndex: number): FighterOriginalClip | undefined {',
        '  return FIGHTERS[character]?.clips[sequenceIndex];',
        '}',
        '',
        '/** The sequence index of an original sequence name, such as "walk alternate". */',
        'export function originalClipNamed(character: number, name: string): number | undefined {',
        '  return FIGHTERS[character]?.names.get(name);',
        '}',
        '',
        '/** Every original sequence name with its index. */',
        'export function originalClipNames(character: number): ReadonlyMap<string, number> {',
        '  return FIGHTERS[character]?.names ?? new Map();',
        '}',
    ].join('\n') + '\n';
}

/** One fighter's white body model. */
export const whiteModelFile = (path: string) => `${WHITE_PRODUCER}\nexport const whiteModel = ${JSON.stringify(path)};\n`;

/** The white body index, by character. */
export function whiteModelIndex(characters: readonly number[]): string {
    return [WHITE_PRODUCER,
        '// Each fighter\'s white body is in white-models/<slug>.ts, which a re-export rewrites alone; this index changes only when a fighter is added.',
        ...characters.map(character => `import * as ${shardName(fighterArt(character).slug)} from "./white-models/${fighterArt(character).slug}";`),
        'export const WHITE_FIGHTER_MODELS: Readonly<Record<number, string>> = {',
        ...characters.map(character => `  ${character}: ${shardName(fighterArt(character).slug)}.whiteModel,`),
        '};',
    ].join('\n') + '\n';
}

/** One fighter's white body facts, keyed by lowercase model path. */
export const whiteFactsFile = (facts: Readonly<Record<string, ModelFacts>>) =>
    `${WHITE_PRODUCER}\nimport type { ModelFacts } from "wisp/scripts/wisp/models";\nexport const whiteModelFacts: Readonly<Record<string, ModelFacts>> = ${JSON.stringify(facts, null, 2)};\n`;

/** The white body facts index: the listed fighters' facts in table order. */
export function whiteFactsIndex(characters: readonly number[]): string {
    return [WHITE_PRODUCER,
        '// Each fighter\'s white body facts are in white-facts/<slug>.ts, which a re-export rewrites alone; this index changes only when a fighter is added.',
        'import type { ModelFacts } from "wisp/scripts/wisp/models";',
        ...characters.map(character => `import * as ${shardName(fighterArt(character).slug)} from "./white-facts/${fighterArt(character).slug}";`),
        'export const WHITE_MODEL_FACTS: Readonly<Record<string, ModelFacts>> = {',
        ...characters.map(character => `  ...${shardName(fighterArt(character).slug)}.whiteModelFacts,`),
        '};',
    ].join('\n') + '\n';
}
